{
  "refused": false,
  "answer": "When a police officer makes an arrest, the officer must record in writing the reasons for the arrest, take any offensive weapons seized from the arrested person to the court or the officer before whom the arrest must be produced, and, without unnecessary delay, bring the arrested person before a magistrate having jurisdiction or the officer in charge of a police‑station. The officer may not keep the person in custody for longer than is reasonable under the circumstances, and, unless a special order is obtained, detention must not exceed twenty‑four hours exclusive of travel time to the magistrate’s court.",
  "citations": [
    {
      "section": "54",
      "quote": "the police-officer shall record while making such arrest, his reasons in writing"
    },
    {
      "section": "53",
      "quote": "the officer or other person making any arrest under this Code may take from the person arrested any offensive weapons which he has about his person, and shall deliver all weapons so taken to the Court or officer before which or whom the officer or person making the arrest is required by this Code to produce the person arrested."
    },
    {
      "section": "60",
      "quote": "A police-officer making an arrest without warrant shall, without unnecessary delay and subject to the provisions herein contained as to bail, take or send the person arrested before a Magistrate having jurisdiction in the case, or before the officer in charge of a police-station."
    },
    {
      "section": "61",
      "quote": "No police-officer shall detain in custody a person arrested without warrant for a longer period than under all the circumstances of the case is reasonable, and such period shall not, in the absence of a special order of a Magistrate under section 167, exceed twenty-four hours exclusive of the time necessary for the journey from the place of arrest to the Magistrate's Court."
    }
  ]
}

